"""
Visual Inspection & Defect Root-Cause Assistant
Streamlit main application
"""
import io
import os
import sys
from pathlib import Path

import pandas as pd
import streamlit as st
from PIL import Image

# ── Path setup ────────────────────────────────────────────────────────────────
ROOT = Path(__file__).parent
sys.path.insert(0, str(ROOT))

from modules.defect_detector  import load_model, run_inference
from modules.defect_registry  import DefectRegistry
from modules.production_analyzer import load_csv, analyze, compare_models, estimate_wip
from modules.root_cause       import correlate, drift_analysis, flag_novel
from modules.profitability    import compute_financials, what_if, impact_delta
from utils.chart_helpers      import (
    defect_donut, defect_type_bar, confidence_histogram, defect_trend,
    utilization_bar, waiting_time_bar, multi_model_radar,
    financial_waterfall, margin_comparison_bar,
)
from utils.constants import DEFECT_CLASSES, STATUS_COLORS

# ─────────────────────────────────────────────────────────────────────────────
# Page Config
# ─────────────────────────────────────────────────────────────────────────────
st.set_page_config(
    page_title="Industrial AI Platform",
    layout="wide",
    initial_sidebar_state="expanded",
)

# ── Clean Industrial UI Styling ──────────────────────────────────────────────
st.markdown("""
<style>
    /* Global Background & Font */
    .stApp {
        background-color: #0b0f19;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    }

    /* Headers */
    h1, h2, h3, h4, h5, h6 {
        color: #f8fafc !important;
        font-weight: 700 !important;
        letter-spacing: -0.2px;
    }

    /* Clean Card Accents */
    .st-emotion-cache-1r6slb0, .st-emotion-cache-12w0qpk, [data-testid="stVerticalBlockBorderWrapper"] {
        background-color: #111827;
        border-color: #1f293d !important;
        border-radius: 10px !important;
    }

    /* Badges */
    .badge {
        display: inline-block;
        padding: 3px 10px;
        border-radius: 6px;
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.6px;
        text-transform: uppercase;
    }
    .badge-DEFECT    { background: #ef4444; color: #ffffff; }
    .badge-PASS      { background: #10b981; color: #ffffff; }
    .badge-UNCERTAIN { background: #f59e0b; color: #ffffff; }
    .badge-NOVEL     { background: #8b5cf6; color: #ffffff; }
    .badge-HIGH      { background: #ef4444; color: #ffffff; }
    .badge-MEDIUM    { background: #f59e0b; color: #ffffff; }
    .badge-LOW       { background: #64748b; color: #ffffff; }

    /* Evidence Cards */
    .evidence-box {
        background: #151e30;
        border: 1px solid #23314a;
        border-radius: 8px;
        padding: 14px 16px;
        margin-bottom: 12px;
        border-left: 4px solid #3b82f6;
    }
    .evidence-box.HIGH   { border-left-color: #ef4444; }
    .evidence-box.MEDIUM { border-left-color: #f59e0b; }
    .evidence-box.LOW    { border-left-color: #64748b; }

    /* Metric Cards */
    .metric-pane {
        background: #141c2c;
        border: 1px solid #233048;
        border-radius: 8px;
        padding: 14px 16px;
        margin-bottom: 10px;
    }

    /* Tabs Styling */
    .stTabs [data-baseweb="tab-list"] {
        gap: 8px;
        margin-bottom: 16px;
    }
    .stTabs [data-baseweb="tab"] {
        font-size: 14px;
        font-weight: 600;
        padding: 10px 20px;
        background-color: #111827;
        border: 1px solid #1f293d;
        border-radius: 8px;
        color: #94a3b8;
    }
    .stTabs [aria-selected="true"] {
        background-color: #1e293b !important;
        color: #ffffff !important;
        border-color: #3b82f6 !important;
    }
</style>
""", unsafe_allow_html=True)

# ─────────────────────────────────────────────────────────────────────────────
# Session State Initialisation
# ─────────────────────────────────────────────────────────────────────────────
if 'registry' not in st.session_state:
    st.session_state.registry = DefectRegistry()
if 'annotated_images' not in st.session_state:
    st.session_state.annotated_images = {}
if 'model_data' not in st.session_state:
    st.session_state.model_data = {}
if 'analyses' not in st.session_state:
    st.session_state.analyses = {}
if 'yolo_model' not in st.session_state:
    st.session_state.yolo_model = None
if 'model_load_error' not in st.session_state:
    st.session_state.model_load_error = None

# ─────────────────────────────────────────────────────────────────────────────
# Sidebar
# ─────────────────────────────────────────────────────────────────────────────
with st.sidebar:
    st.subheader("System Control")
    st.caption("AI Model, Ingestion & Economic Settings")
    st.divider()

    # AI Model Engine
    with st.container(border=True):
        st.markdown("**AI Model Engine**")
        custom_pt = st.text_input(
            "Weights File (.pt)",
            placeholder=r"D:\acceleration\best.pt",
            label_visibility="collapsed",
        )
        if st.button("Load / Reload Model", use_container_width=True):
            with st.spinner("Initializing YOLOv8 engine..."):
                mdl, err = load_model(custom_pt or None)
                st.session_state.yolo_model = mdl
                st.session_state.model_load_error = err
            if mdl:
                st.success("Model ready.")
            else:
                st.error(f"Error: {err}")

        # Auto-load on initial run
        if st.session_state.yolo_model is None and st.session_state.model_load_error is None:
            mdl, err = load_model(custom_pt or None)
            st.session_state.yolo_model = mdl
            st.session_state.model_load_error = err

        if st.session_state.yolo_model:
            st.caption("Status: Model Active (YOLOv8-cls)")
        elif st.session_state.model_load_error:
            st.caption(f"Status: {st.session_state.model_load_error[:60]}...")

    # Inspection Boundary
    with st.container(border=True):
        st.markdown("**Decision Threshold**")
        conf_threshold = st.slider(
            "Confidence Cutoff",
            min_value=0.20, max_value=0.90, value=0.45, step=0.05,
            help="Confidence >= Cutoff: Classified. Below Cutoff: UNCERTAIN. < 0.25: NOVEL.",
        )

    # Production CSVs
    with st.container(border=True):
        st.markdown("**Production Datasets**")

        def _upload_csv(label, key):
            f = st.file_uploader(label, type=['csv'], key=key)
            if f:
                df, err = load_csv(f)
                if err:
                    st.error(f"Parse error: {err}")
                else:
                    name = label.split(' ')[0]
                    st.session_state.model_data[name] = df
                    st.session_state.analyses[name] = analyze(df)
                    st.success(f"Loaded {f.name} ({len(df)} rows)")

        _upload_csv("Model 1 CSV", "csv1")
        _upload_csv("Model 2 CSV", "csv2")
        _upload_csv("Model 3 CSV", "csv3")

        # Auto-load if available in project directory
        if not st.session_state.model_data:
            default_paths = {
                'Model 1': r'D:\acceleration\Model 1.csv',
                'Model 2': r'D:\acceleration\Model 2.csv',
                'Model 3': r'D:\acceleration\Model 3.csv',
            }
            for name, path in default_paths.items():
                if os.path.exists(path) and name not in st.session_state.model_data:
                    df, _ = load_csv(path)
                    if df is not None:
                        st.session_state.model_data[name] = df
                        st.session_state.analyses[name] = analyze(df)

        if st.session_state.model_data:
            st.caption(f"Active Models: {', '.join(st.session_state.model_data.keys())}")

    # Economic Cost Parameters
    with st.container(border=True):
        st.markdown("**Economic Sliders**")
        scrap_cost = st.slider(
            "Scrap Unit Cost ($)",
            min_value=5.0, max_value=50.0, value=15.0, step=0.5,
            format="$%.2f",
        )
        downtime_cost = st.slider(
            "Downtime Cost ($/min)",
            min_value=1.0, max_value=10.0, value=2.50, step=0.25,
            format="$%.2f",
        )
        revenue_mult = st.slider(
            "Revenue Multiplier",
            min_value=1.5, max_value=8.0, value=4.0, step=0.5,
            help="Unit Selling Price = Scrap Cost x Multiplier",
        )

    if st.button("Reset Inspection Session", use_container_width=True):
        st.session_state.registry.clear()
        st.session_state.annotated_images.clear()
        st.success("Session reset.")

# ─────────────────────────────────────────────────────────────────────────────
# Main Header
# ─────────────────────────────────────────────────────────────────────────────
with st.container(border=True):
    st.title("Visual Inspection & Defect Root-Cause Assistant")
    st.caption("Unified Quality Intelligence, Process Bottleneck Diagnostics & Economic Optimization")

summary    = st.session_state.registry.summary()
analyses   = st.session_state.analyses
registry   = st.session_state.registry

# ── Summary KPI Strip ─────────────────────────────────────────────────────────
with st.container(border=True):
    k1, k2, k3, k4, k5 = st.columns(5)
    with k1:
        st.metric("Units Inspected", summary.get('total', 0))
    with k2:
        st.metric("Defects Identified", summary.get('defect', 0),
                  delta=f"{summary.get('defect_rate', 0):.1f}% defect rate",
                  delta_color="inverse")
    with k3:
        st.metric("Review Required", f"{summary.get('uncertain', 0)} / {summary.get('novel', 0)}")
    with k4:
        st.metric("Simulation Models", len(analyses))
    with k5:
        st.metric("Inference Engine", "Active" if st.session_state.yolo_model else "Inactive")

# ─────────────────────────────────────────────────────────────────────────────
# TABS
# ─────────────────────────────────────────────────────────────────────────────
tab1, tab2, tab3, tab4 = st.tabs([
    "Quality Inspection",
    "Production Flow Health",
    "Root Cause Analysis",
    "Profitability & What-If Simulator",
])

# ═════════════════════════════════════════════════════════════════════════════
# TAB 1 — QUALITY INSPECTION
# ═════════════════════════════════════════════════════════════════════════════
with tab1:
    # ── Block 1: Ingestion ────────────────────────────────────────────────────
    with st.container(border=True):
        st.subheader("Batch Inspection Ingestion")
        st.caption("Upload product surface images for automated YOLOv8 classification and neural Grad-CAM localization.")

        uploaded_files = st.file_uploader(
            "Select product surface images",
            type=['jpg', 'jpeg', 'png', 'bmp', 'tiff'],
            accept_multiple_files=True,
            key="img_upload",
            label_visibility="collapsed",
        )

        if uploaded_files:
            if not st.session_state.yolo_model:
                st.error("YOLOv8 model not loaded. Please verify the model file in the sidebar.")
            else:
                if st.button("Run Visual Inspection on Batch", type="primary", use_container_width=True):
                    progress_bar = st.progress(0)
                    for i, f in enumerate(uploaded_files):
                        img = Image.open(io.BytesIO(f.read())).convert('RGB')
                        result = run_inference(img, st.session_state.yolo_model, conf_threshold)
                        st.session_state.registry.add(f.name, result)
                        st.session_state.annotated_images[f.name] = result
                        progress_bar.progress((i + 1) / len(uploaded_files))

                    st.success(f"Batch completed: {len(uploaded_files)} unit(s) evaluated.")

    # ── Block 2: Gallery Grid ─────────────────────────────────────────────────
    reg_df  = registry.to_dataframe()
    summary = registry.summary()

    if not reg_df.empty and st.session_state.annotated_images:
        with st.container(border=True):
            st.subheader("Inspection Results Gallery")
            st.caption("Unit-by-unit classification telemetry and visual evidence overlays.")

            filter_col1, filter_col2 = st.columns([1, 2])
            with filter_col1:
                gal_filter = st.selectbox(
                    "Filter Results",
                    ["All Units", "Defects Only", "Passed Units", "Uncertain / Novel"],
                    key="gal_filter_sel",
                )
            with filter_col2:
                vis_mode = st.radio(
                    "Display Mode",
                    ["Clean Industrial View", "Grad-CAM Heatmap", "Bounding Box", "Raw Image"],
                    horizontal=True,
                    key="vis_mode_sel",
                )

            items = list(st.session_state.annotated_images.items())
            if gal_filter == "Defects Only":
                items = [it for it in items if it[1]['status'] == 'DEFECT']
            elif gal_filter == "Passed Units":
                items = [it for it in items if it[1]['status'] == 'PASS']
            elif gal_filter == "Uncertain / Novel":
                items = [it for it in items if it[1]['status'] in ('UNCERTAIN', 'NOVEL')]

            if not items:
                st.info(f"No inspected units match the selected filter: '{gal_filter}'")
            else:
                num_cols = 3
                for row_idx in range(0, len(items), num_cols):
                    row_items = items[row_idx:row_idx + num_cols]
                    cols = st.columns(num_cols)
                    for col_idx, (fname, res) in enumerate(row_items):
                        with cols[col_idx]:
                            with st.container(border=True):
                                stat = res['status']
                                dtype = res['defect_type'].upper()
                                conf = res['confidence'] * 100
                                bbox = res.get('bbox')

                                top_l, top_r = st.columns([2, 1])
                                with top_l:
                                    st.markdown(f"**{fname}**")
                                with top_r:
                                    st.markdown(f"<div style='text-align:right;'><span class='badge badge-{stat}'>{stat}</span></div>", unsafe_allow_html=True)

                                if vis_mode == "Grad-CAM Heatmap" and res.get('heatmap_image'):
                                    st.image(res['heatmap_image'], use_container_width=True)
                                elif vis_mode == "Bounding Box" and res.get('boxed_image'):
                                    st.image(res['boxed_image'], use_container_width=True)
                                elif vis_mode == "Raw Image" and res.get('raw_image'):
                                    st.image(res['raw_image'], use_container_width=True)
                                elif res.get('annotated_image'):
                                    st.image(res['annotated_image'], use_container_width=True)

                                st.markdown(f"**Class:** `{dtype}` &nbsp;|&nbsp; **Confidence:** `{conf:.1f}%`")
                                if bbox and vis_mode == "Bounding Box":
                                    x1, y1, x2, y2 = [int(v) for v in bbox]
                                    st.caption(f"Target Box: `[{x1}, {y1}, {x2}, {y2}]` ({x2-x1}x{y2-y1}px)")
                                else:
                                    st.caption(f"Evaluation: **{stat}** (AI Neural Inference)")

                                if res.get('class_probs'):
                                    with st.expander("Probability Distribution"):
                                        for c_name, c_prob in sorted(res['class_probs'].items(), key=lambda x: x[1], reverse=True):
                                            st.progress(min(1.0, float(c_prob)), text=f"{c_name.capitalize()}: {c_prob*100:.1f}%")

        # ── Block 3: Analytics & Log Table ────────────────────────────────────
        with st.container(border=True):
            st.subheader("Batch Analytics & Telemetry Log")
            r1, r2 = st.columns([1, 2])
            with r1:
                st.plotly_chart(defect_donut(summary), use_container_width=True, key="quality_donut_chart")
                if summary.get('by_type'):
                    st.plotly_chart(defect_type_bar(summary['by_type']), use_container_width=True, key="quality_type_bar_chart")

            with r2:
                st.markdown("##### Detailed Log Table")
                styled = reg_df.copy()
                styled['Status'] = styled['status']
                st.dataframe(
                    styled[['unit_id', 'image_name', 'defect_type', 'confidence', 'Status', 'timestamp']],
                    use_container_width=True, height=270,
                )
                if len(reg_df) >= 3:
                    drift_df = registry.drift_dataframe()
                    st.plotly_chart(defect_trend(drift_df), use_container_width=True, key="quality_defect_trend_chart")

            if len(reg_df[reg_df['status'] != 'PASS']) > 0:
                st.plotly_chart(confidence_histogram(reg_df), use_container_width=True, key="quality_conf_hist_chart")

            flagged = flag_novel(reg_df)
            if not flagged.empty:
                st.warning(f"**{len(flagged)} unit(s) flagged for quality review** (UNCERTAIN or NOVEL detections)")
                st.dataframe(flagged, use_container_width=True)
    else:
        st.info("Upload images above and click 'Run Visual Inspection on Batch' to begin analysis.")

# ═════════════════════════════════════════════════════════════════════════════
# TAB 2 — PRODUCTION FLOW
# ═════════════════════════════════════════════════════════════════════════════
with tab2:
    if not analyses:
        st.info("Load Model 1/2/3 CSV datasets in the sidebar to activate production flow analysis.")
    else:
        # ── Block 1: Production Overview ──────────────────────────────────────
        with st.container(border=True):
            st.subheader("Production Line Performance & Theory of Constraints")
            st.caption("Multi-stage capacity utilization, queue times, and Little's Law WIP analysis from Rockwell Arena simulations.")

            model_names = list(analyses.keys())
            sel_model   = st.selectbox("Select Production Model", model_names, index=0)
            analysis    = analyses.get(sel_model)

            if analysis is None:
