        revenue_mult = st.slider(
            "Revenue Multiplier",
            min_value=1.5, max_value=8.0, value=4.0, step=0.5,
            help="Unit Selling Price = Scrap Cost x Multiplier",
        )

    if st.button("Reset Inspection Session", use_container_width=True):
        st.session_state.registry.clear()
        st.session_state.annotated_images.clear()
        st.success("Session reset.")

# ─────────────────────────────────────────────────────────────────────────────
# Main Header
# ─────────────────────────────────────────────────────────────────────────────
with st.container(border=True):
    st.title("Visual Inspection & Defect Root-Cause Assistant")
    st.caption("Unified Quality Intelligence, Process Bottleneck Diagnostics & Economic Optimization")

summary    = st.session_state.registry.summary()
analyses   = st.session_state.analyses
registry   = st.session_state.registry

# ── Summary KPI Strip ─────────────────────────────────────────────────────────
with st.container(border=True):
    k1, k2, k3, k4, k5 = st.columns(5)
    with k1:
        st.metric("Units Inspected", summary.get('total', 0))
    with k2:
        st.metric("Defects Identified", summary.get('defect', 0),
                  delta=f"{summary.get('defect_rate', 0):.1f}% defect rate",
                  delta_color="inverse")
    with k3:
        st.metric("Review Required", f"{summary.get('uncertain', 0)} / {summary.get('novel', 0)}")
    with k4:
        st.metric("Simulation Models", len(analyses))
    with k5:
        st.metric("Inference Engine", "Active" if st.session_state.yolo_model else "Inactive")

# ─────────────────────────────────────────────────────────────────────────────
# TABS
# ─────────────────────────────────────────────────────────────────────────────
tab1, tab2, tab3, tab4 = st.tabs([
    "Quality Inspection",
    "Production Flow Health",
    "Root Cause Analysis",
    "Profitability & What-If Simulator",
])

# ═════════════════════════════════════════════════════════════════════════════
# TAB 1 — QUALITY INSPECTION
# ═════════════════════════════════════════════════════════════════════════════
with tab1:
    # ── Block 1: Ingestion ────────────────────────────────────────────────────
    with st.container(border=True):
        st.subheader("Batch Inspection Ingestion")
        st.caption("Upload product surface images for automated YOLOv8 classification and neural Grad-CAM localization.")

        uploaded_files = st.file_uploader(
            "Select product surface images",
            type=['jpg', 'jpeg', 'png', 'bmp', 'tiff'],
            accept_multiple_files=True,
            key="img_upload",
            label_visibility="collapsed",
        )

        if uploaded_files:
            if not st.session_state.yolo_model:
                st.error("YOLOv8 model not loaded. Please verify the model file in the sidebar.")
            else:
                if st.button("Run Visual Inspection on Batch", type="primary", use_container_width=True):
                    progress_bar = st.progress(0)
                    for i, f in enumerate(uploaded_files):
                        img = Image.open(io.BytesIO(f.read())).convert('RGB')
                        result = run_inference(img, st.session_state.yolo_model, conf_threshold)
                        st.session_state.registry.add(f.name, result)
                        st.session_state.annotated_images[f.name] = result
                        progress_bar.progress((i + 1) / len(uploaded_files))

                    st.success(f"Batch completed: {len(uploaded_files)} unit(s) evaluated.")

    # ── Block 2: Gallery Grid ─────────────────────────────────────────────────
    reg_df  = registry.to_dataframe()
    summary = registry.summary()

    if not reg_df.empty and st.session_state.annotated_images:
        with st.container(border=True):
            st.subheader("Inspection Results Gallery")
            st.caption("Unit-by-unit classification telemetry, bounding boxes, and Grad-CAM neural evidence overlays.")

            filter_col1, filter_col2 = st.columns([1, 2])
            with filter_col1:
                gal_filter = st.selectbox(
                    "Filter Results",
                    ["All Units", "Defects Only", "Passed Units", "Uncertain / Novel"],
                    key="gal_filter_sel",
                )
            with filter_col2:
                vis_mode = st.radio(
                    "Display Mode",
                    ["Bounding Box", "Grad-CAM Heatmap", "Clean Industrial View", "Raw Image"],
                    index=0,
                    horizontal=True,
                    key="vis_mode_sel",
                )

            items = list(st.session_state.annotated_images.items())
            if gal_filter == "Defects Only":
                items = [it for it in items if it[1]['status'] == 'DEFECT']
            elif gal_filter == "Passed Units":
                items = [it for it in items if it[1]['status'] == 'PASS']
            elif gal_filter == "Uncertain / Novel":
                items = [it for it in items if it[1]['status'] in ('UNCERTAIN', 'NOVEL')]

            if not items:
                st.info(f"No inspected units match the selected filter: '{gal_filter}'")
            else:
                num_cols = 3
                for row_idx in range(0, len(items), num_cols):
                    row_items = items[row_idx:row_idx + num_cols]
                    cols = st.columns(num_cols)
                    for col_idx, (fname, res) in enumerate(row_items):
                        with cols[col_idx]:
                            with st.container(border=True):
                                stat = res['status']
                                dtype = res['defect_type'].upper()
                                conf = res['confidence'] * 100
                                bbox = res.get('bbox')

                                top_l, top_r = st.columns([2, 1])
                                with top_l:
                                    st.markdown(f"**{fname}**")
                                with top_r:
                                    st.markdown(f"<div style='text-align:right;'><span class='badge badge-{stat}'>{stat}</span></div>", unsafe_allow_html=True)

                                if vis_mode == "Bounding Box" and res.get('boxed_image'):
                                    st.image(res['boxed_image'], use_container_width=True)
                                elif vis_mode == "Grad-CAM Heatmap" and res.get('heatmap_image'):
                                    st.image(res['heatmap_image'], use_container_width=True)
                                elif vis_mode == "Clean Industrial View" and res.get('annotated_image'):
                                    st.image(res['annotated_image'], use_container_width=True)
                                elif vis_mode == "Raw Image" and res.get('raw_image'):
                                    st.image(res['raw_image'], use_container_width=True)
                                elif res.get('annotated_image'):
                                    st.image(res['annotated_image'], use_container_width=True)

                                st.markdown(f"**Class:** `{dtype}` &nbsp;|&nbsp; **Confidence:** `{conf:.1f}%`")
                                if bbox:
                                    x1, y1, x2, y2 = [int(v) for v in bbox]
                                    st.caption(f"Target BBox: `[{x1}, {y1}, {x2}, {y2}]` ({x2-x1}x{y2-y1}px)")
                                else:
                                    st.caption(f"Evaluation: **{stat}** (AI Neural Inference)")

                                if res.get('class_probs'):
                                    with st.expander("Probability Distribution"):
                                        for c_name, c_prob in sorted(res['class_probs'].items(), key=lambda x: x[1], reverse=True):
                                            st.progress(min(1.0, float(c_prob)), text=f"{c_name.capitalize()}: {c_prob*100:.1f}%")

        # ── Block 3: Analytics & Log Table ────────────────────────────────────
        with st.container(border=True):
            st.subheader("Batch Analytics & Telemetry Log")
            r1, r2 = st.columns([1, 2])
            with r1:
                st.plotly_chart(defect_donut(summary), use_container_width=True, key="quality_donut_chart")
                if summary.get('by_type'):
                    st.plotly_chart(defect_type_bar(summary['by_type']), use_container_width=True, key="quality_type_bar_chart")

            with r2:
                st.markdown("##### Detailed Log Table")
                styled = reg_df.copy()
                styled['Status'] = styled['status']
                st.dataframe(
                    styled[['unit_id', 'image_name', 'defect_type', 'confidence', 'Status', 'timestamp']],
                    use_container_width=True, height=270,
                )
                if len(reg_df) >= 3:
                    drift_df = registry.drift_dataframe()
                    st.plotly_chart(defect_trend(drift_df), use_container_width=True, key="quality_defect_trend_chart")

            if len(reg_df[reg_df['status'] != 'PASS']) > 0:
                st.plotly_chart(confidence_histogram(reg_df), use_container_width=True, key="quality_conf_hist_chart")

            flagged = flag_novel(reg_df)
            if not flagged.empty:
                st.warning(f"**{len(flagged)} unit(s) flagged for quality review** (UNCERTAIN or NOVEL detections)")
                st.dataframe(flagged, use_container_width=True)
    else:
        st.info("Upload images above and click 'Run Visual Inspection on Batch' to begin analysis.")

# ═════════════════════════════════════════════════════════════════════════════
# TAB 2 — PRODUCTION FLOW
# ═════════════════════════════════════════════════════════════════════════════
with tab2:
    if not analyses:
        st.info("Load Model 1/2/3 (.csv or .xlsx) datasets in the sidebar to activate production flow analysis.")
    else:
        # ── Block 1: Production Overview ──────────────────────────────────────
        with st.container(border=True):
            st.subheader("Production Line Performance & Theory of Constraints")
            st.caption("Multi-stage capacity utilization, queue times, and Little's Law WIP analysis from Rockwell Arena simulations.")

            model_names = list(analyses.keys())
            sel_model   = st.selectbox("Select Production Model", model_names, index=0)
            analysis    = analyses.get(sel_model)

            if analysis is None:
                st.error(f"Unable to parse telemetry for {sel_model}.")
            else:
                m1, m2, m3, m4 = st.columns(4)
                m1.metric("Production Demand", f"{analysis['demand']:.0f} units")
                m2.metric("Parts Produced",    f"{analysis['total_parts']:.0f} units")
                m3.metric("Throughput Rate",   f"{analysis['throughput_efficiency']:.1f}%",
                          delta=f"{analysis['throughput_gap']:.0f} units shortage",
                          delta_color="inverse")
                m4.metric("Line Speed",        f"{analysis['parts_per_hour']:.1f} parts/hr")

        if analysis is not None:
            # ── Block 2: Bottleneck Spotlight ─────────────────────────────────
            with st.container(border=True):
                st.subheader("System Bottleneck Diagnosis")
                bn = analysis['bottleneck_station']
                bu = analysis['bottleneck_util'] * 100
                bw = analysis['bottleneck_wait']

                if bu > 85:
                    level = "CRITICAL"
                elif bu > 70:
                    level = "WARNING"
                else:
                    level = "OPTIMAL"

                st.markdown(f"""
<div class="evidence-box {'HIGH' if level == 'CRITICAL' else 'MEDIUM' if level == 'WARNING' else 'LOW'}">
  <div style="display:flex; justify-content:space-between; align-items:center;">
    <b>Primary Constraint Station: {bn}</b>
    <span class="badge badge-{level}">{level}</span>
  </div>
  <div style="margin-top:8px;">
    <b>Capacity Utilisation:</b> {bu:.1f}% &nbsp;|&nbsp;
    <b>Average Queue Delay:</b> {bw:.1f} min &nbsp;|&nbsp;
    <b>Throughput Deficit:</b> {analysis['throughput_gap']:.0f} units
  </div>
  <small style="color:#94a3b8">Elevating capacity at this constraint station yields the highest ROI on overall line output.</small>
</div>
""", unsafe_allow_html=True)

            # ── Block 3: Station Telemetry Charts ─────────────────────────────
            with st.container(border=True):
                st.subheader("Station Capacity & Queue Latency")
                ch1, ch2 = st.columns(2)
                with ch1:
                    st.plotly_chart(utilization_bar(analysis['stations'], sel_model),
                                    use_container_width=True, key=f"flow_util_{sel_model}")
                with ch2:
                    st.plotly_chart(waiting_time_bar(analysis['stations'], sel_model),
                                    use_container_width=True, key=f"flow_wait_{sel_model}")

            # ── Block 4: WIP Estimate ─────────────────────────────────────────
            wip = estimate_wip(analysis)
            if any(v > 0 for v in wip.values()):
                with st.container(border=True):
                    st.subheader("Estimated Work-in-Process (Little's Law)")
                    wip_cols = st.columns(len(wip))
                    for col, (station, count) in zip(wip_cols, wip.items()):
                        col.metric(f"{station} WIP Buffer", f"~{count:.0f} units")

            # ── Block 5: Multi-Model Benchmark ────────────────────────────────
            if len(analyses) > 1:
                with st.container(border=True):
                    st.subheader("Cross-Model Scenario Benchmark")
                    comp_df = compare_models(analyses)
                    st.dataframe(comp_df, use_container_width=True)

                    if len(analyses) >= 2:
                        st.plotly_chart(multi_model_radar(analyses), use_container_width=True, key="flow_radar_chart")

# ═════════════════════════════════════════════════════════════════════════════
# TAB 3 — ROOT CAUSE ANALYSIS
# ═════════════════════════════════════════════════════════════════════════════
with tab3:
    no_quality = registry.to_dataframe().empty
    no_process = not analyses

    if no_quality and no_process:
        st.info("Upload inspection images and production datasets to generate causal links.")
    else:
        # ── Block 1: Causal Correlation ───────────────────────────────────────
        with st.container(border=True):
            st.subheader("Root-Cause Causal Correlation Engine")
            st.caption("Evidence-based correlation linking process line overloads with physical defect manifestations.")

            rc_model = st.selectbox(
                "Select Baseline Production Model",
                list(analyses.keys()) if analyses else ['No model loaded'],
                key='rc_model_sel',
            )
            rc_analysis  = analyses.get(rc_model) if analyses else None
            rc_defect_sum = registry.summary()

            evidence = correlate(rc_analysis, rc_defect_sum if not no_quality else None)

            if not evidence:
                st.success("No critical process-quality correlations detected under current operating conditions.")
            else:
                st.markdown(f"**{len(evidence)} Causal Correlation Rule(s) Triggered**")
                for card in evidence:
                    conf  = card['confidence']
                    obs   = card['defect_observed']
                    cls   = conf
                    html = f"""
<div class="evidence-box {cls}">
  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
    <b>PROBABLE CAUSE: {card['cause']}</b>
    <span class="badge badge-{conf}">{conf} CONFIDENCE</span>
  </div>
  <small><b>Telemetry Evidence:</b> {card['evidence']}</small><br>
  <small><b>Associated Defect Signatures:</b> {', '.join(card['related_defects']) if card['related_defects'] else 'General throughput bottleneck'}
  {'&nbsp; <span class="badge badge-DEFECT">OBSERVED IN BATCH</span>' if obs else ''}</small><br>
  <hr style="margin:8px 0; border-color:#24324c">
  <small><b>Recommended Corrective Action:</b> {card['action']}</small>
</div>
"""
                    st.markdown(html, unsafe_allow_html=True)

        # ── Block 2: Drift Monitoring ─────────────────────────────────────────
        with st.container(border=True):
            st.subheader("Batch-to-Batch Defect Drift")
            if no_quality or len(registry) < 2:
                st.info("Inspect at least 2 units in Tab 1 to track process drift.")
            else:
                drift_df_raw = registry.drift_dataframe()
                drift        = drift_analysis(drift_df_raw)

                if drift:
                    dc1, dc2, dc3 = st.columns(3)
                    dc1.metric("Drift Trajectory", drift['trend'])
                    dc2.metric("Drift Rate", f"{drift['slope']:+.2f} pp/unit")
                    dc3.metric("Flagged Review Units", drift['novel_count'] + drift['uncertain_count'])

                    st.plotly_chart(defect_trend(drift['df']), use_container_width=True, key="rootcause_defect_trend_chart")

        # ── Block 3: Out-of-Distribution Registry ─────────────────────────────
        if not no_quality:
            flagged = flag_novel(registry.to_dataframe())
            if not flagged.empty:
                with st.container(border=True):
                    st.subheader("Out-of-Distribution & Human Review Registry")
                    st.warning(f"**{len(flagged)} Novel / Uncertain Unit(s)** — Flagged for manual engineering review.")
                    st.dataframe(flagged, use_container_width=True)

# ═════════════════════════════════════════════════════════════════════════════
# TAB 4 — PROFITABILITY & RECOMMENDATIONS
# ═════════════════════════════════════════════════════════════════════════════
with tab4:
    if not analyses:
        st.info("Upload production CSV or Excel datasets in the sidebar to activate the financial engine.")
    else:
        # ── Block 1: Baseline Economics ───────────────────────────────────────
        with st.container(border=True):
            st.subheader("Baseline Economic Impact & Loss Waterfall")
            st.caption("Financial translation of scrap losses, bottleneck idle time, and opportunity costs.")

            fin_model = st.selectbox(
                "Select Financial Model Target",
                list(analyses.keys()),
                key='fin_model_sel',
            )
            fin_analysis  = analyses.get(fin_model)
            fin_defect_sum = registry.summary() if not registry.to_dataframe().empty else None

            if fin_analysis is None:
                st.error("Unable to load financial model data.")
            else:
                baseline = compute_financials(
                    fin_analysis, fin_defect_sum, scrap_cost, downtime_cost, revenue_mult
                )

                fb1, fb2, fb3, fb4, fb5 = st.columns(5)
                fb1.metric("Gross Revenue",    f"${baseline['gross_revenue']:,.0f}")
                fb2.metric("Scrap Loss",       f"${baseline['scrap_loss']:,.0f}", delta_color="inverse")
                fb3.metric("Idle Cost",        f"${baseline['bottleneck_idle_loss']:,.0f}", delta_color="inverse")
                fb4.metric("Opportunity Loss", f"${baseline['opportunity_loss']:,.0f}", delta_color="inverse")
                fb5.metric("Operating Margin",
                           f"${baseline['net_margin']:,.0f}",
                           delta=f"{baseline['margin_pct']:.1f}%",
                           delta_color="normal" if baseline['net_margin'] > 0 else "inverse")

                wf1, wf2 = st.columns([3, 2])
                with wf1:
                    st.plotly_chart(financial_waterfall(baseline, fin_model), use_container_width=True, key=f"fin_waterfall_{fin_model}")

                with wf2:
                    st.markdown("##### Direct Loss Breakdown")
                    loss_items = {
                        "Scrap Material Losses": baseline['scrap_loss'],
                        "Bottleneck Idle Overhead": baseline['bottleneck_idle_loss'],
                        "Market Opportunity Deficit": baseline['opportunity_loss'],
                        "Estimated Rework Cost": baseline['rework_cost'],
                    }
                    for label, val in loss_items.items():
                        pct = val / baseline['total_loss'] * 100 if baseline['total_loss'] else 0
                        st.markdown(f"""
<div class="metric-pane">
  <b>{label}</b><br>
  <span style="font-size:18px; font-weight:700; color:#ef4444">${val:,.2f}</span>
  <span style="color:#94a3b8"> ({pct:.0f}% of total)</span>
</div>
""", unsafe_allow_html=True)

        # ── Block 2: What-If Simulator ────────────────────────────────────────
        with st.container(border=True):
            st.subheader("What-If Scenario Simulation Engine")
            st.caption("Model projected margin lift from targeted scrap reduction and bottleneck idle mitigation.")

            col_s1, col_s2 = st.columns(2)
            with col_s1:
                util_impr = st.slider(
                    "Bottleneck Idle Time Reduction (%)",
                    0, 50, 15, step=5,
                    help="Simulates capacity elevation at the bottleneck station.",
                )
            with col_s2:
                scrap_redn = st.slider(
                    "Defect / Scrap Rate Reduction (%)",
                    0, 80, 20, step=5,
                    help="Simulates visual inspection quality improvements.",
                )

            wi_result = what_if(
                fin_analysis, fin_defect_sum,
                scrap_cost, downtime_cost,
                util_impr, scrap_redn, revenue_mult,
            )
            delta = impact_delta(baseline, wi_result)

            w1, w2, w3 = st.columns(3)
            w1.metric("Projected Net Margin",
                      f"${wi_result['net_margin']:,.0f}",
                      delta=f"+${delta['delta_margin']:,.0f} gain",
                      delta_color="normal")
            w2.metric("Total Losses Recovered",
                      f"${delta['delta_loss_saved']:,.0f}",
                      delta=f"{delta['margin_improvement_pct']:+.1f}% margin lift")
            w3.metric("Scrap Reduction",
                      f"{wi_result['scrap_units']:.0f} units",
                      delta=f"{baseline['scrap_units'] - wi_result['scrap_units']:.0f} units saved",
                      delta_color="inverse")

        # ── Block 3: Multi-Model Benchmark ────────────────────────────────────
        if len(analyses) > 1:
            with st.container(border=True):
                st.subheader("Multi-Model Scenario Profitability")
                all_results = {}
                for name, an in analyses.items():
                    if an is None:
                        continue
                    b = compute_financials(an, fin_defect_sum, scrap_cost, downtime_cost, revenue_mult)
                    wi = what_if(an, fin_defect_sum, scrap_cost, downtime_cost,
                                 util_impr, scrap_redn, revenue_mult)
                    all_results[name] = {'baseline': b, 'whatif': wi}

                st.plotly_chart(margin_comparison_bar(all_results), use_container_width=True, key="fin_margin_comp_chart")

        # ── Block 4: Recommendations & Export ─────────────────────────────────
        with st.container(border=True):
            st.subheader("Actionable Engineering Recommendations")
            recs = []
            evidence = correlate(fin_analysis, fin_defect_sum)
            for card in evidence[:3]:
                recs.append({
                    'priority': card['confidence'],
                    'title':    card['cause'],
                    'action':   card['action'],
                    'impact':   "Direct scrap reduction and buffer stabilization",
                })

            if fin_analysis.get('throughput_gap', 0) > 10:
                recs.insert(0, {
                    'priority': 'HIGH',
                    'title':    f"Elevate {fin_analysis['bottleneck_station']} station capacity",
                    'action':   (
                        f"{fin_analysis['bottleneck_station']} is operating at "
                        f"{fin_analysis['bottleneck_util']*100:.0f}% capacity utilisation — the primary constraint. "
                        "Add parallel station tooling or schedule shift balancing. "
                        f"Closing the {fin_analysis['throughput_gap']:.0f}-unit gap could recover "
                        f"~${fin_analysis['throughput_gap'] * scrap_cost * revenue_mult:,.0f} in unrealized revenue."
                    ),
                    'impact': f"~${fin_analysis['throughput_gap'] * scrap_cost * revenue_mult:,.0f} revenue recovery",
                })

            priority_labels = {'HIGH': '[HIGH PRIORITY]', 'MEDIUM': '[MEDIUM PRIORITY]', 'LOW': '[LOW PRIORITY]'}
            for i, rec in enumerate(recs[:4], 1):
                p = rec['priority']
                st.markdown(f"""
<div class="evidence-box {p}">
  <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
    <b>{priority_labels.get(p,'')}&nbsp; #{i} — {rec['title']}</b>
    <span class="badge badge-{p}">{p}</span>
  </div>
  <small>{rec['action']}</small><br>
  <small style="color:#10b981"><b>Projected Impact:</b> {rec.get('impact','—')}</small>
</div>
""", unsafe_allow_html=True)

            st.divider()

            report_lines = [
                "# Industrial Decision-Support & Quality Intelligence Report",
                f"\n## Quality Summary",
                f"- Total Units Evaluated: {summary.get('total',0)}",
                f"- Defective Units: {summary.get('defect',0)} ({summary.get('defect_rate',0):.1f}%)",
                f"- Uncertain Classifications: {summary.get('uncertain',0)} | Novel Signatures: {summary.get('novel',0)}",
                f"\n## Production Flow ({fin_model})",
                f"- Demand Target: {fin_analysis['demand']} | Total Output: {fin_analysis['total_parts']}",
                f"- Throughput Efficiency: {fin_analysis['throughput_efficiency']:.1f}%",
                f"- Bottleneck Station: {fin_analysis['bottleneck_station']} @ {fin_analysis['bottleneck_util']*100:.1f}% utilisation",
                f"\n## Financial Baseline Snapshot",
                f"- Gross Revenue: ${baseline['gross_revenue']:,.2f}",
                f"- Total Incurred Losses: ${baseline['total_loss']:,.2f}",
                f"- Net Operating Margin: ${baseline['net_margin']:,.2f} ({baseline['margin_pct']:.1f}%)",
                f"\n## What-If Optimization ({util_impr}% idle reduction, {scrap_redn}% scrap reduction)",
                f"- Projected Operating Margin: ${wi_result['net_margin']:,.2f}",
                f"- Economic Improvement: +${delta['delta_margin']:,.2f} (+{delta['margin_improvement_pct']:.1f}%)",
                f"\n## Actionable Recommendations",
            ]
            for i, rec in enumerate(recs[:4], 1):
                report_lines.append(f"{i}. [{rec['priority']}] {rec['title']}: {rec['action']}")

            report_text = "\n".join(report_lines)
            st.download_button(
                "Export Comprehensive Executive Report (.md)",
                data=report_text,
                file_name="industrial_intelligence_report.md",
                mime="text/markdown",
                use_container_width=True,
                type="primary",
            )

# ─────────────────────────────────────────────────────────────────────────────
# Minimal Clean Footer
# ─────────────────────────────────────────────────────────────────────────────
st.caption("<center style='color:#64748b; margin-top:20px;'>Industrial Quality Intelligence & Decision-Support System</center>", unsafe_allow_html=True)

