"""
Visual Inspection & Defect Root-Cause Assistant
Streamlit main application with futuristic industrial command-center aesthetic
"""
import io
import os
import sys
from pathlib import Path

import pandas as pd
import streamlit as st
from PIL import Image

# ── Path setup ────────────────────────────────────────────────────────────────
ROOT = Path(__file__).parent
sys.path.insert(0, str(ROOT))

from modules.defect_detector  import load_model, run_inference
from modules.defect_registry  import DefectRegistry
from modules.production_analyzer import load_dataset, load_csv, analyze, compare_models, estimate_wip
from modules.root_cause       import correlate, drift_analysis, flag_novel
from modules.profitability    import compute_financials, what_if, impact_delta
from utils.chart_helpers      import (
    defect_donut, defect_type_bar, confidence_histogram, defect_trend,
    utilization_bar, waiting_time_bar, multi_model_radar,
    financial_waterfall, margin_comparison_bar,
)
from utils.constants import DEFECT_CLASSES, STATUS_COLORS

# ─────────────────────────────────────────────────────────────────────────────
# Page Config
# ─────────────────────────────────────────────────────────────────────────────
st.set_page_config(
    page_title="Industrial AI Platform",
    layout="wide",
    initial_sidebar_state="expanded",
)

# ── Futuristic Cyber Industrial UI Styling ────────────────────────────────────
st.markdown("""
<style>
    @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Rajdhani:wght@500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');

    /* Global Cyber Canvas */
    .stApp {
        background-color: #050711;
        background-image: 
            radial-gradient(at 0% 0%, rgba(0, 240, 255, 0.08) 0px, transparent 50%),
            radial-gradient(at 100% 0%, rgba(139, 92, 246, 0.08) 0px, transparent 50%),
            radial-gradient(at 50% 100%, rgba(16, 185, 129, 0.05) 0px, transparent 50%);
        font-family: 'Rajdhani', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        letter-spacing: 0.2px;
    }

    /* Headers with Futuristic Font */
    h1, h2, h3 {
        font-family: 'Orbitron', -apple-system, sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 0.8px !important;
        color: #f8fafc !important;
        text-shadow: 0 0 20px rgba(0, 240, 255, 0.15);
    }
    h4, h5, h6 {
        font-family: 'Rajdhani', sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 0.5px !important;
        color: #e2e8f0 !important;
    }

    /* Futuristic Card Containers */
    [data-testid="stVerticalBlockBorderWrapper"] {
        background: rgba(11, 17, 33, 0.75) !important;
        border: 1px solid rgba(0, 240, 255, 0.16) !important;
        border-radius: 12px !important;
        backdrop-filter: blur(16px) !important;
        -webkit-backdrop-filter: blur(16px) !important;
        box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.45), inset 0 1px 0 0 rgba(0, 240, 255, 0.15) !important;
        transition: border-color 0.3s ease, box-shadow 0.3s ease;
    }
    [data-testid="stVerticalBlockBorderWrapper"]:hover {
        border-color: rgba(0, 240, 255, 0.32) !important;
        box-shadow: 0 10px 40px 0 rgba(0, 240, 255, 0.1), inset 0 1px 0 0 rgba(0, 240, 255, 0.25) !important;
    }

    /* Live Telemetry Pulse Dot */
    .pulse-dot {
        display: inline-block;
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background-color: #00f0ff;
        box-shadow: 0 0 10px #00f0ff;
        animation: pulse_glow 2s infinite ease-in-out;
        margin-right: 6px;
        vertical-align: middle;
    }
    .pulse-dot.green {
        background-color: #10b981;
        box-shadow: 0 0 10px #10b981;
    }
    @keyframes pulse_glow {
        0% { transform: scale(0.95); opacity: 0.8; box-shadow: 0 0 4px currentColor; }
        50% { transform: scale(1.25); opacity: 1; box-shadow: 0 0 14px currentColor; }
        100% { transform: scale(0.95); opacity: 0.8; box-shadow: 0 0 4px currentColor; }
    }

    /* Futuristic HUD Telemetry Banner */
    .hud-banner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        background: linear-gradient(90deg, rgba(0, 240, 255, 0.08) 0%, rgba(139, 92, 246, 0.04) 100%);
        border: 1px solid rgba(0, 240, 255, 0.25);
        border-radius: 10px;
        padding: 10px 18px;
        margin-bottom: 12px;
        font-family: 'JetBrains Mono', monospace;
        font-size: 11px;
        color: #94a3b8;
        letter-spacing: 0.8px;
    }
    .hud-banner .status-val {
        color: #00f0ff;
        font-weight: 700;
    }

    /* Badges */
    .badge {
        display: inline-block;
        padding: 4px 12px;
        border-radius: 4px;
        font-family: 'JetBrains Mono', monospace;
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 0.8px;
        text-transform: uppercase;
        border: 1px solid transparent;
    }
    .badge-DEFECT    { background: rgba(239, 68, 68, 0.15); color: #ff3366; border-color: rgba(239, 68, 68, 0.4); box-shadow: 0 0 10px rgba(239, 68, 68, 0.2); }
    .badge-PASS      { background: rgba(16, 185, 129, 0.15); color: #05df9d; border-color: rgba(16, 185, 129, 0.4); box-shadow: 0 0 10px rgba(16, 185, 129, 0.2); }
    .badge-UNCERTAIN { background: rgba(245, 158, 11, 0.15); color: #ffaa00; border-color: rgba(245, 158, 11, 0.4); box-shadow: 0 0 10px rgba(245, 158, 11, 0.2); }
    .badge-NOVEL     { background: rgba(139, 92, 246, 0.15); color: #c084fc; border-color: rgba(139, 92, 246, 0.4); box-shadow: 0 0 10px rgba(139, 92, 246, 0.2); }
    .badge-CRITICAL  { background: rgba(239, 68, 68, 0.15); color: #ff3366; border-color: rgba(239, 68, 68, 0.4); box-shadow: 0 0 10px rgba(239, 68, 68, 0.2); }
    .badge-WARNING   { background: rgba(245, 158, 11, 0.15); color: #ffaa00; border-color: rgba(245, 158, 11, 0.4); box-shadow: 0 0 10px rgba(245, 158, 11, 0.2); }
    .badge-OPTIMAL   { background: rgba(16, 185, 129, 0.15); color: #05df9d; border-color: rgba(16, 185, 129, 0.4); box-shadow: 0 0 10px rgba(16, 185, 129, 0.2); }
    .badge-HIGH      { background: rgba(239, 68, 68, 0.15); color: #ff3366; border-color: rgba(239, 68, 68, 0.4); }
    .badge-MEDIUM    { background: rgba(245, 158, 11, 0.15); color: #ffaa00; border-color: rgba(245, 158, 11, 0.4); }
    .badge-LOW       { background: rgba(100, 116, 139, 0.15); color: #94a3b8; border-color: rgba(100, 116, 139, 0.4); }

    /* Evidence Box */
    .evidence-box {
        background: rgba(15, 23, 42, 0.85);
        border: 1px solid rgba(0, 240, 255, 0.18);
        border-radius: 8px;
        padding: 16px 18px;
        margin-bottom: 12px;
        border-left: 4px solid #00f0ff;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
    }
    .evidence-box.HIGH     { border-left-color: #ff3366; }
    .evidence-box.CRITICAL { border-left-color: #ff3366; }
    .evidence-box.MEDIUM   { border-left-color: #ffaa00; }
    .evidence-box.WARNING  { border-left-color: #ffaa00; }
    .evidence-box.LOW      { border-left-color: #64748b; }
    .evidence-box.OPTIMAL  { border-left-color: #05df9d; }

    /* Metric Pane */
    .metric-pane {
        background: rgba(13, 20, 38, 0.7);
        border: 1px solid rgba(0, 240, 255, 0.15);
        border-radius: 8px;
        padding: 14px 16px;
        margin-bottom: 10px;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }

    /* Tabs Styling */
    .stTabs [data-baseweb="tab-list"] {
        gap: 10px;
        margin-bottom: 18px;
        background: rgba(11, 17, 33, 0.6);
        padding: 6px;
        border-radius: 12px;
        border: 1px solid rgba(0, 240, 255, 0.12);
    }
    .stTabs [data-baseweb="tab"] {
        font-family: 'Rajdhani', sans-serif;
        font-size: 15px;
        font-weight: 700;
        letter-spacing: 0.6px;
        padding: 10px 22px;
        background-color: transparent;
        border: 1px solid transparent;
        border-radius: 8px;
        color: #94a3b8;
        transition: all 0.25s ease;
    }
    .stTabs [data-baseweb="tab"]:hover {
        color: #00f0ff;
        background-color: rgba(0, 240, 255, 0.06);
    }
    .stTabs [aria-selected="true"] {
        background: linear-gradient(135deg, rgba(0, 240, 255, 0.15) 0%, rgba(59, 130, 246, 0.15) 100%) !important;
        color: #00f0ff !important;
        border-color: rgba(0, 240, 255, 0.4) !important;
        box-shadow: 0 0 15px rgba(0, 240, 255, 0.15);
    }

    /* Streamlit Metrics */
    [data-testid="stMetricValue"] {
        font-family: 'JetBrains Mono', monospace !important;
        font-weight: 700 !important;
        color: #f8fafc !important;
    }
    [data-testid="stMetricLabel"] {
        font-family: 'Rajdhani', sans-serif !important;
        font-size: 13px !important;
        font-weight: 600 !important;
        letter-spacing: 0.6px !important;
        text-transform: uppercase !important;
        color: #94a3b8 !important;
    }

    /* Cyber Buttons */
    .stButton>button {
        font-family: 'Rajdhani', sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 0.8px !important;
        text-transform: uppercase !important;
        border-radius: 8px !important;
        border: 1px solid rgba(0, 240, 255, 0.3) !important;
        background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%) !important;
        color: #f8fafc !important;
        transition: all 0.25s ease !important;
    }
    .stButton>button:hover {
        border-color: #00f0ff !important;
        box-shadow: 0 0 18px rgba(0, 240, 255, 0.35) !important;
        transform: translateY(-1px);
    }
    .stButton>button[kind="primary"] {
        background: linear-gradient(135deg, #0077b6 0%, #00b4d8 100%) !important;
        border-color: #00f0ff !important;
        color: #ffffff !important;
        box-shadow: 0 0 15px rgba(0, 240, 255, 0.25) !important;
    }
    .stButton>button[kind="primary"]:hover {
        box-shadow: 0 0 25px rgba(0, 240, 255, 0.55) !important;
    }
</style>
""", unsafe_allow_html=True)

# ─────────────────────────────────────────────────────────────────────────────
# Session State Initialisation
# ─────────────────────────────────────────────────────────────────────────────
if 'registry' not in st.session_state:
    st.session_state.registry = DefectRegistry()
if 'annotated_images' not in st.session_state:
    st.session_state.annotated_images = {}
if 'model_data' not in st.session_state:
    st.session_state.model_data = {}
if 'analyses' not in st.session_state:
    st.session_state.analyses = {}
if 'yolo_model' not in st.session_state:
    st.session_state.yolo_model = None
if 'model_load_error' not in st.session_state:
    st.session_state.model_load_error = None

# ─────────────────────────────────────────────────────────────────────────────
# Sidebar
# ─────────────────────────────────────────────────────────────────────────────
with st.sidebar:
    st.markdown("### SYSTEM CONTROL")
    st.caption("AI Neural Engine, Telemetry Ingestion & Economic Parameters")
    st.divider()

    # AI Model Engine
    with st.container(border=True):
        st.markdown("**NEURAL INFERENCE ENGINE**")
        custom_pt = st.text_input(
            "Weights File (.pt)",
            placeholder=r"D:\acceleration\best.pt",
            label_visibility="collapsed",
        )
        if st.button("Initialize Neural Core", use_container_width=True):
            with st.spinner("Compiling YOLOv8 neural pipeline..."):
                mdl, err = load_model(custom_pt or None)
                st.session_state.yolo_model = mdl
                st.session_state.model_load_error = err
            if mdl:
                st.success("Neural Core Active.")
            else:
                st.error(f"Error: {err}")

        # Auto-load on initial run
        if st.session_state.yolo_model is None and st.session_state.model_load_error is None:
            mdl, err = load_model(custom_pt or None)
            st.session_state.yolo_model = mdl
            st.session_state.model_load_error = err

        if st.session_state.yolo_model:
            st.markdown("<small><span class='pulse-dot green'></span> <b>STATUS:</b> ACTIVE (YOLOv8 Core)</small>", unsafe_allow_html=True)
        elif st.session_state.model_load_error:
            st.caption(f"Status: {st.session_state.model_load_error[:55]}...")

    # Inspection Boundary
    with st.container(border=True):
        st.markdown("**DECISION BOUNDARY**")
        conf_threshold = st.slider(
            "Confidence Cutoff",
            min_value=0.20, max_value=0.90, value=0.45, step=0.05,
            help="Confidence >= Cutoff: Classified. Below Cutoff: UNCERTAIN. < 0.25: NOVEL.",
        )

    # Production Datasets (.CSV, .XLSX, .XLS)
    with st.container(border=True):
        st.markdown("**TELEMETRY DATASETS**")
        st.caption("Upload .csv, .xlsx, or .xls Arena simulations")

        def _upload_dataset(label, model_key, uploader_key):
            f = st.file_uploader(label, type=['csv', 'xlsx', 'xls'], key=uploader_key)
            if f:
                df, err = load_dataset(f)
                if err:
                    st.error(f"Error reading {f.name}: {err}")
                else:
                    st.session_state.model_data[model_key] = df
                    analysis = analyze(df)
                    if analysis:
                        st.session_state.analyses[model_key] = analysis
                        st.success(f"Loaded {model_key} ({len(df)} rows)")
                    else:
                        st.warning(f"Loaded {model_key}, but no station telemetry recognized.")

        _upload_dataset("Model 1 Telemetry (.csv / .xlsx)", "Model 1", "upload_m1")
        _upload_dataset("Model 2 Telemetry (.csv / .xlsx)", "Model 2", "upload_m2")
        _upload_dataset("Model 3 Telemetry (.csv / .xlsx)", "Model 3", "upload_m3")

        # Auto-load if available in project directory
        if not st.session_state.model_data:
            default_path_candidates = {
                'Model 1': [
                    r'D:\acceleration\Model_1.csv', r'D:\acceleration\Model 1.csv',
                    r'D:\acceleration\Model_1.xlsx', r'D:\acceleration\Model 1.xlsx',
                ],
                'Model 2': [
                    r'D:\acceleration\Model_2.csv', r'D:\acceleration\Model 2.csv',
                    r'D:\acceleration\Model_2.xlsx', r'D:\acceleration\Model 2.xlsx',
                ],
                'Model 3': [
                    r'D:\acceleration\Model_3.csv', r'D:\acceleration\Model 3.csv',
                    r'D:\acceleration\Model_3.xlsx', r'D:\acceleration\Model 3.xlsx',
                ],
            }
            for model_name, path_list in default_path_candidates.items():
                if model_name not in st.session_state.model_data:
                    for p in path_list:
                        if os.path.exists(p):
                            df, err = load_dataset(p)
                            if df is not None:
                                st.session_state.model_data[model_name] = df
                                st.session_state.analyses[model_name] = analyze(df)
                                break

        if st.session_state.model_data:
            st.caption(f"Active Models: {', '.join(st.session_state.model_data.keys())}")

    # Economic Cost Parameters
    with st.container(border=True):
        st.markdown("**ECONOMIC PARAMETERS**")
        scrap_cost = st.slider(
            "Scrap Unit Cost ($)",
            min_value=5.0, max_value=50.0, value=15.0, step=0.5,
            format="$%.2f",
        )
        downtime_cost = st.slider(
            "Downtime Cost ($/min)",
            min_value=1.0, max_value=10.0, value=2.50, step=0.25,
            format="$%.2f",
        )
        revenue_mult = st.slider(
            "Revenue Multiplier",
            min_value=1.5, max_value=8.0, value=4.0, step=0.5,
            help="Unit Selling Price = Scrap Cost x Multiplier",
        )

    if st.button("Reset Inspection Session", use_container_width=True):
        st.session_state.registry.clear()
        st.session_state.annotated_images.clear()
        st.success("Session reset.")

# ─────────────────────────────────────────────────────────────────────────────
# Main Command Header & HUD Telemetry Strip
# ─────────────────────────────────────────────────────────────────────────────
with st.container(border=True):
    h_col1, h_col2 = st.columns([3, 1])
    with h_col1:
        st.title("Autonomous Quality & Process Intelligence")
        st.caption("YOLOv8 Neural Vision Engine • Theory of Constraints Bottleneck Diagnostics • Predictive Financial Optimization")
    with h_col2:
        st.markdown("""
<div style="text-align:right; margin-top:10px;">
  <span class="badge badge-PASS"><span class="pulse-dot green"></span>SYSTEM ONLINE</span><br>
  <small style="color:#64748b; font-family:'JetBrains Mono';">LATENCY: 12ms | LEVEL-4 AI</small>
</div>
""", unsafe_allow_html=True)

    # Live HUD Telemetry Strip
    st.markdown("""
<div class="hud-banner">
  <div><span class="pulse-dot"></span>NEURAL INFERENCE: <span class="status-val">GRAD-CAM ACTIVE</span></div>
  <div>TOC CAPACITY ENGINE: <span class="status-val">MULTI-STAGE ARMORED</span></div>
  <div>SIMULATION PROTOCOL: <span class="status-val">ARENA v16.2 COMPATIBLE</span></div>
  <div>ACCURACY CUTOFF: <span class="status-val">DYNAMIC</span></div>
</div>
""", unsafe_allow_html=True)

summary    = st.session_state.registry.summary()
analyses   = st.session_state.analyses
registry   = st.session_state.registry

# ── Summary KPI Strip ─────────────────────────────────────────────────────────
with st.container(border=True):
    k1, k2, k3, k4, k5 = st.columns(5)
    with k1:
        st.metric("Units Inspected", summary.get('total', 0))
    with k2:
        st.metric("Defects Identified", summary.get('defect', 0),
                  delta=f"{summary.get('defect_rate', 0):.1f}% defect rate",
                  delta_color="inverse")
    with k3:
