# ── Futuristic Cyber Industrial UI Styling ────────────────────────────────────
st.markdown("""
<style>
    @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Rajdhani:wght@500;600;700&family=JetBrains+Mono:wght@400;500;700&display=swap');

    /* ══════════════════════════════════════════════
       GLOBAL CANVAS — Deep Space Industrial Theme
    ══════════════════════════════════════════════ */
    .stApp {
        background-color: #020817;
        background-image:
            radial-gradient(ellipse at 0% 0%, rgba(0,240,255,0.10) 0px, transparent 55%),
            radial-gradient(ellipse at 100% 0%, rgba(139,92,246,0.10) 0px, transparent 55%),
            radial-gradient(ellipse at 50% 100%, rgba(5,223,157,0.07) 0px, transparent 55%),
            linear-gradient(rgba(0,240,255,0.025) 1px, transparent 1px),
            linear-gradient(90deg, rgba(0,240,255,0.025) 1px, transparent 1px);
        background-size: 100% 100%, 100% 100%, 100% 100%, 40px 40px, 40px 40px;
        font-family: 'Rajdhani', -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        letter-spacing: 0.3px;
        color: #e2e8f0;
    }

    /* ══════════════════════════════════════════════
       CUSTOM SCROLLBARS
    ══════════════════════════════════════════════ */
    ::-webkit-scrollbar { width: 5px; height: 5px; }
    ::-webkit-scrollbar-track { background: #020817; }
    ::-webkit-scrollbar-thumb { background: rgba(0,240,255,0.3); border-radius: 10px; }
    ::-webkit-scrollbar-thumb:hover { background: #00f0ff; box-shadow: 0 0 8px #00f0ff; }

    /* ══════════════════════════════════════════════
       TYPOGRAPHY SYSTEM
    ══════════════════════════════════════════════ */
    h1, h2, h3 {
        font-family: 'Orbitron', sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 1px !important;
        color: #f8fafc !important;
        text-shadow: 0 0 30px rgba(0,240,255,0.2);
    }
    h4, h5, h6 {
        font-family: 'Rajdhani', sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 0.5px !important;
        color: #e2e8f0 !important;
    }
    p, span, label {
        color: #cbd5e1 !important;
    }
    [data-testid="stCaptionContainer"], [data-testid="stCaptionContainer"] p {
        color: #64748b !important;
        font-size: 12.5px !important;
    }
    strong, b { color: #f8fafc !important; }

    /* ══════════════════════════════════════════════
       SIDEBAR — Dark Frosted Glass Panel
    ══════════════════════════════════════════════ */
    [data-testid="stSidebar"] {
        background: linear-gradient(180deg, #050d1f 0%, #020817 100%) !important;
        border-right: 1px solid rgba(0,240,255,0.12) !important;
        box-shadow: 4px 0 24px rgba(0,0,0,0.5) !important;
    }
    [data-testid="stSidebar"] * { color: #cbd5e1; }
    [data-testid="stSidebar"] h3 {
        font-family: 'Orbitron', sans-serif !important;
        font-size: 13px !important;
        letter-spacing: 2px !important;
        color: #00f0ff !important;
        border-bottom: 1px solid rgba(0,240,255,0.2);
        padding-bottom: 8px !important;
        text-shadow: 0 0 12px rgba(0,240,255,0.5) !important;
    }

    /* ══════════════════════════════════════════════
       HEADER BAR
    ══════════════════════════════════════════════ */
    [data-testid="stHeader"] {
        background: rgba(2,8,23,0.85) !important;
        backdrop-filter: blur(16px) !important;
        border-bottom: 1px solid rgba(0,240,255,0.1) !important;
    }

    /* ══════════════════════════════════════════════
       FROSTED GLASS CARDS
    ══════════════════════════════════════════════ */
    [data-testid="stVerticalBlockBorderWrapper"] {
        background: rgba(8,14,30,0.75) !important;
        border: 1px solid rgba(0,240,255,0.14) !important;
        border-radius: 14px !important;
        backdrop-filter: blur(24px) !important;
        -webkit-backdrop-filter: blur(24px) !important;
        box-shadow:
            0 8px 32px rgba(0,0,0,0.6),
            inset 0 1px 0 rgba(0,240,255,0.12),
            inset 0 -1px 0 rgba(0,0,0,0.3) !important;
        transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    }
    [data-testid="stVerticalBlockBorderWrapper"]:hover {
        border-color: rgba(0,240,255,0.32) !important;
        box-shadow:
            0 16px 48px rgba(0,0,0,0.7),
            0 0 0 1px rgba(0,240,255,0.08),
            inset 0 1px 0 rgba(0,240,255,0.25) !important;
        transform: translateY(-1px);
    }

    /* ══════════════════════════════════════════════
       NAVIGATION TABS
    ══════════════════════════════════════════════ */
    .stTabs [data-baseweb="tab-list"] {
        gap: 6px;
        margin-bottom: 20px;
        background: rgba(8,14,30,0.8);
        padding: 5px 6px;
        border-radius: 12px;
        border: 1px solid rgba(0,240,255,0.15);
        box-shadow: inset 0 1px 0 rgba(0,240,255,0.08);
    }
    .stTabs [data-baseweb="tab"] {
        font-family: 'Rajdhani', sans-serif !important;
        font-size: 14px;
        font-weight: 700;
        letter-spacing: 0.8px;
        padding: 9px 22px;
        border-radius: 8px;
        color: #64748b;
        border: 1px solid transparent;
        transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
        text-transform: uppercase;
    }
    .stTabs [data-baseweb="tab"]:hover {
        color: #00f0ff;
        background: rgba(0,240,255,0.07);
        border-color: rgba(0,240,255,0.18);
    }
    .stTabs [aria-selected="true"] {
        background: linear-gradient(135deg, rgba(0,240,255,0.18) 0%, rgba(59,130,246,0.15) 100%) !important;
        color: #00f0ff !important;
        border-color: rgba(0,240,255,0.42) !important;
        box-shadow: 0 0 20px rgba(0,240,255,0.18), inset 0 1px 0 rgba(0,240,255,0.3);
    }

    /* ══════════════════════════════════════════════
       METRICS
    ══════════════════════════════════════════════ */
    [data-testid="stMetricValue"] {
        font-family: 'JetBrains Mono', monospace !important;
        font-weight: 700 !important;
        font-size: 1.6rem !important;
        color: #f8fafc !important;
    }
    [data-testid="stMetricLabel"] {
        font-family: 'Rajdhani', sans-serif !important;
        font-size: 11px !important;
        font-weight: 700 !important;
        letter-spacing: 1.2px !important;
        text-transform: uppercase !important;
        color: #475569 !important;
    }
    [data-testid="stMetricDelta"] {
        font-family: 'JetBrains Mono', monospace !important;
        font-size: 12px !important;
    }
    [data-testid="stMetric"] {
        background: rgba(8,14,30,0.6) !important;
        border: 1px solid rgba(0,240,255,0.1) !important;
        border-radius: 10px !important;
        padding: 12px 16px !important;
    }

    /* ══════════════════════════════════════════════
       BUTTONS
    ══════════════════════════════════════════════ */
    .stButton > button {
        font-family: 'Rajdhani', sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 1px !important;
        text-transform: uppercase !important;
        border-radius: 8px !important;
        border: 1px solid rgba(0,240,255,0.28) !important;
        background: linear-gradient(135deg, rgba(15,23,42,0.9) 0%, rgba(30,41,59,0.9) 100%) !important;
        color: #e2e8f0 !important;
        transition: all 0.2s cubic-bezier(0.16,1,0.3,1) !important;
        height: 40px !important;
    }
    .stButton > button:hover {
        border-color: #00f0ff !important;
        color: #00f0ff !important;
        box-shadow: 0 0 20px rgba(0,240,255,0.3), 0 4px 12px rgba(0,0,0,0.4) !important;
        transform: translateY(-2px) !important;
    }
    .stButton > button[kind="primary"] {
        background: linear-gradient(135deg, #0369a1 0%, #0ea5e9 100%) !important;
        border-color: rgba(14,165,233,0.6) !important;
        color: #ffffff !important;
        box-shadow: 0 0 16px rgba(14,165,233,0.3) !important;
    }
    .stButton > button[kind="primary"]:hover {
        box-shadow: 0 0 28px rgba(0,240,255,0.5), 0 6px 16px rgba(0,0,0,0.4) !important;
        transform: translateY(-2px) !important;
    }

    /* ══════════════════════════════════════════════
       FORM ELEMENTS — INPUTS, SELECTS, SLIDERS
    ══════════════════════════════════════════════ */
    input, textarea {
        background-color: #0a1628 !important;
        color: #f8fafc !important;
        border: 1px solid rgba(0,240,255,0.2) !important;
        border-radius: 8px !important;
        font-family: 'JetBrains Mono', monospace !important;
    }
    input:focus, textarea:focus {
        border-color: rgba(0,240,255,0.5) !important;
        box-shadow: 0 0 0 3px rgba(0,240,255,0.1) !important;
    }
    [data-baseweb="base-input"], [data-baseweb="input"] {
        background-color: #0a1628 !important;
        border-color: rgba(0,240,255,0.2) !important;
    }
    [data-baseweb="select"] > div {
        background-color: #0a1628 !important;
        color: #f8fafc !important;
        border: 1px solid rgba(0,240,255,0.2) !important;
        border-radius: 8px !important;
    }
    [data-baseweb="popover"], [data-baseweb="menu"], [role="listbox"] {
        background-color: #0a1628 !important;
        border: 1px solid rgba(0,240,255,0.25) !important;
        border-radius: 10px !important;
        box-shadow: 0 20px 40px rgba(0,0,0,0.7) !important;
    }
    [data-baseweb="menu"] li, [role="option"] {
        color: #cbd5e1 !important;
        background-color: transparent !important;
        border-radius: 6px !important;
        margin: 2px 4px !important;
    }
    [data-baseweb="menu"] li:hover, [role="option"]:hover {
        background-color: rgba(0,240,255,0.12) !important;
        color: #00f0ff !important;
    }
    [role="option"][aria-selected="true"] {
        background-color: rgba(0,240,255,0.18) !important;
        color: #00f0ff !important;
    }
    .stSlider > div > div > div {
        background: rgba(0,240,255,0.15) !important;
    }
    .stSlider > div > div > div > div {
        background: #00f0ff !important;
        box-shadow: 0 0 10px rgba(0,240,255,0.5) !important;
    }

    /* ══════════════════════════════════════════════
       FILE UPLOADER
    ══════════════════════════════════════════════ */
    [data-testid="stFileUploader"] {
        background: rgba(8,14,30,0.6) !important;
    }
    [data-testid="stFileUploaderDropzone"] {
        background: rgba(8,14,30,0.5) !important;
        border: 2px dashed rgba(0,240,255,0.22) !important;
        border-radius: 12px !important;
        transition: all 0.2s ease !important;
    }
    [data-testid="stFileUploaderDropzone"]:hover {
        border-color: rgba(0,240,255,0.5) !important;
        background: rgba(0,240,255,0.05) !important;
    }
    [data-testid="stFileUploaderDropzone"] * { color: #64748b !important; }

    /* ══════════════════════════════════════════════
       DATAFRAMES & TABLES
    ══════════════════════════════════════════════ */
    [data-testid="stDataFrame"] {
        border: 1px solid rgba(0,240,255,0.12) !important;
        border-radius: 10px !important;
        overflow: hidden !important;
    }
    .stDataFrame thead tr th {
        background: rgba(0,240,255,0.08) !important;
        color: #00f0ff !important;
        font-family: 'Rajdhani', sans-serif !important;
        font-weight: 700 !important;
        letter-spacing: 0.8px !important;
        text-transform: uppercase !important;
        font-size: 12px !important;
    }
    .stDataFrame tbody tr:hover td {
        background: rgba(0,240,255,0.06) !important;
    }

    /* ══════════════════════════════════════════════
       EXPANDERS
    ══════════════════════════════════════════════ */
    [data-testid="stExpander"] {
        background: rgba(8,14,30,0.5) !important;
        border: 1px solid rgba(0,240,255,0.12) !important;
        border-radius: 10px !important;
        overflow: hidden !important;
    }
    details summary {
        color: #94a3b8 !important;
        font-family: 'Rajdhani', sans-serif !important;
        font-weight: 600 !important;
        padding: 10px 0 !important;
    }
    details summary:hover { color: #00f0ff !important; }

    /* ══════════════════════════════════════════════
       RADIO & CHECKBOX
    ══════════════════════════════════════════════ */
    [data-testid="stRadio"] label span { color: #94a3b8 !important; }
    [data-testid="stRadio"] label:hover span { color: #00f0ff !important; }

    /* ══════════════════════════════════════════════
       PULSE DOTS — Live Indicators
    ══════════════════════════════════════════════ */
    .pulse-dot {
        display: inline-block; width: 8px; height: 8px;
        border-radius: 50%;
        background: #00f0ff; box-shadow: 0 0 10px #00f0ff;
        animation: pulse_glow 2s infinite ease-in-out;
        margin-right: 6px; vertical-align: middle;
    }
    .pulse-dot.green  { background: #05df9d; box-shadow: 0 0 10px #05df9d; }
    .pulse-dot.red    { background: #ff3366; box-shadow: 0 0 10px #ff3366; }
    .pulse-dot.orange { background: #ffaa00; box-shadow: 0 0 10px #ffaa00; }
    @keyframes pulse_glow {
        0%  { transform: scale(0.90); opacity: 0.7; }
        50% { transform: scale(1.30); opacity: 1.0; }
        100%{ transform: scale(0.90); opacity: 0.7; }
    }

    /* ══════════════════════════════════════════════
       HUD SYSTEM BANNER
    ══════════════════════════════════════════════ */
    .hud-banner {
        display: flex; flex-wrap: wrap; gap: 20px;
        align-items: center; justify-content: space-between;
        background: linear-gradient(90deg,
            rgba(0,240,255,0.06) 0%,
            rgba(139,92,246,0.04) 50%,
            rgba(5,223,157,0.04) 100%);
        border: 1px solid rgba(0,240,255,0.18);
        border-radius: 10px;
        padding: 10px 18px; margin: 12px 0;
        font-family: 'JetBrains Mono', monospace;
        font-size: 10.5px; color: #475569;
        letter-spacing: 0.9px;
    }
    .hud-banner .status-val { color: #00f0ff; font-weight: 700; }

    /* ══════════════════════════════════════════════
       STATUS BADGES
    ══════════════════════════════════════════════ */
    .badge {
        display: inline-flex; align-items: center; gap: 4px;
        padding: 3px 10px; border-radius: 5px;
        font-family: 'JetBrains Mono', monospace;
        font-size: 10px; font-weight: 700;
        letter-spacing: 1px; text-transform: uppercase;
        border: 1px solid transparent;
    }
    .badge-DEFECT  { background: rgba(255,51,102,0.12);  color: #ff3366; border-color: rgba(255,51,102,0.35); }
    .badge-PASS    { background: rgba(5,223,157,0.12);   color: #05df9d; border-color: rgba(5,223,157,0.35); }
    .badge-UNCERTAIN{background: rgba(255,170,0,0.12);   color: #ffaa00; border-color: rgba(255,170,0,0.35); }
    .badge-NOVEL   { background: rgba(191,90,242,0.12);  color: #bf5af2; border-color: rgba(191,90,242,0.35); }
    .badge-CRITICAL{ background: rgba(255,51,102,0.12);  color: #ff3366; border-color: rgba(255,51,102,0.35); box-shadow:0 0 8px rgba(255,51,102,0.2); }
    .badge-WARNING { background: rgba(255,170,0,0.12);   color: #ffaa00; border-color: rgba(255,170,0,0.35); box-shadow:0 0 8px rgba(255,170,0,0.2); }
    .badge-OPTIMAL { background: rgba(5,223,157,0.12);   color: #05df9d; border-color: rgba(5,223,157,0.35); box-shadow:0 0 8px rgba(5,223,157,0.2); }
    .badge-HIGH    { background: rgba(255,51,102,0.12);  color: #ff3366; border-color: rgba(255,51,102,0.35); }
    .badge-MEDIUM  { background: rgba(255,170,0,0.12);   color: #ffaa00; border-color: rgba(255,170,0,0.35); }
    .badge-LOW     { background: rgba(100,116,139,0.12); color: #94a3b8; border-color: rgba(100,116,139,0.35); }

    /* ══════════════════════════════════════════════
       EVIDENCE / ALERT CARDS
    ══════════════════════════════════════════════ */
    .evidence-box {
        background: rgba(8,14,30,0.85);
        border: 1px solid rgba(0,240,255,0.15);
        border-left: 3px solid #00f0ff;
        border-radius: 0 10px 10px 0;
        padding: 14px 18px; margin-bottom: 10px;
        box-shadow: 0 4px 20px rgba(0,0,0,0.4);
        transition: all 0.2s ease;
    }
    .evidence-box:hover { transform: translateX(2px); }
    .evidence-box.HIGH     { border-left-color: #ff3366; box-shadow: 0 4px 20px rgba(255,51,102,0.1); }
    .evidence-box.CRITICAL { border-left-color: #ff3366; box-shadow: 0 4px 20px rgba(255,51,102,0.15); }
    .evidence-box.MEDIUM   { border-left-color: #ffaa00; box-shadow: 0 4px 20px rgba(255,170,0,0.1); }
    .evidence-box.WARNING  { border-left-color: #ffaa00; }
    .evidence-box.LOW      { border-left-color: #334155; }
    .evidence-box.OPTIMAL  { border-left-color: #05df9d; box-shadow: 0 4px 20px rgba(5,223,157,0.1); }

    /* ══════════════════════════════════════════════
       STAT CARD — Custom metric display component
    ══════════════════════════════════════════════ */
    .stat-card {
        background: rgba(8,14,30,0.75);
        border: 1px solid rgba(0,240,255,0.12);
        border-top: 2px solid rgba(0,240,255,0.4);
        border-radius: 12px;
        padding: 16px 18px;
        text-align: center;
        transition: all 0.25s ease;
    }
    .stat-card:hover {
        border-top-color: #00f0ff;
        box-shadow: 0 0 20px rgba(0,240,255,0.12);
    }
    .stat-card .val {
        font-family: 'JetBrains Mono', monospace;
        font-size: 1.8rem; font-weight: 700;
        color: #f8fafc; line-height: 1.1;
    }
    .stat-card .lbl {
        font-family: 'Rajdhani', sans-serif;
        font-size: 11px; font-weight: 700;
        letter-spacing: 1.5px; text-transform: uppercase;
        color: #475569; margin-top: 4px;
    }
    .stat-card .sub {
        font-family: 'JetBrains Mono', monospace;
        font-size: 10px; color: #334155; margin-top: 2px;
    }

    /* ══════════════════════════════════════════════
       SECTION DIVIDER — Glowing line separator
    ══════════════════════════════════════════════ */
    .section-divider {
        height: 1px;
        background: linear-gradient(90deg,
            transparent 0%,
            rgba(0,240,255,0.3) 30%,
            rgba(0,240,255,0.5) 50%,
            rgba(0,240,255,0.3) 70%,
            transparent 100%);
        margin: 20px 0;
        box-shadow: 0 0 8px rgba(0,240,255,0.2);
    }

    /* ══════════════════════════════════════════════
       PROGRESS BAR — Custom utilisation bar
    ══════════════════════════════════════════════ */
    .util-bar-wrap {
        background: rgba(0,240,255,0.06);
        border: 1px solid rgba(0,240,255,0.1);
        border-radius: 6px; height: 8px;
        overflow: hidden; margin: 6px 0;
