    .stSlider [data-baseweb="slider"] div[role="slider"] {
        background: #ffffff !important;
        border: 3.5px solid #0284c7 !important;
        box-shadow: 0 0 16px rgba(56, 189, 248, 0.95), 0 2px 8px rgba(0, 0, 0, 0.7) !important;
