        background: #090e1a !important;
        border: 1px solid rgba(56, 189, 248, 0.45) !important;
        border-radius: 6px !important;
        padding: 2px 7px !important;
    }
    .stSlider [data-testid="stSliderTickBar"] {
        color: #64748b !important;
        font-family: 'JetBrains Mono', monospace !important;
        font-size: 10.5px !important;
    }

    /* ══════════════════════════════════════════════
       STATUS INDICATOR DOTS
    ══════════════════════════════════════════════ */
    .pulse-dot {
        display: inline-block; width: 7px; height: 7px;
        border-radius: 50%;
        background: #38bdf8; box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
        animation: pulse_glow 2.5s infinite ease-in-out;
        margin-right: 6px; vertical-align: middle;
    }
    .pulse-dot.green  { background: #10b981; box-shadow: 0 0 8px rgba(16, 185, 129, 0.8); }
    .pulse-dot.red    { background: #f43f5e; box-shadow: 0 0 8px rgba(244, 63, 94, 0.8); }
    .pulse-dot.orange { background: #f59e0b; box-shadow: 0 0 8px rgba(245, 158, 11, 0.8); }
    .pulse-dot.purple { background: #a855f7; box-shadow: 0 0 8px rgba(168, 85, 247, 0.8); }
    @keyframes pulse_glow {
        0%  { transform: scale(0.92); opacity: 0.8; }
        50% { transform: scale(1.20); opacity: 1.0; }
        100%{ transform: scale(0.92); opacity: 0.8; }
    }

    /* ══════════════════════════════════════════════
       HUD TELEMETRY BANNER
    ══════════════════════════════════════════════ */
    .hud-banner {
        display: flex; flex-wrap: wrap; gap: 16px;
        align-items: center; justify-content: space-between;
        background: linear-gradient(90deg,
            rgba(56, 189, 248, 0.07) 0%,
            rgba(99, 102, 241, 0.05) 50%,
            rgba(16, 185, 129, 0.04) 100%);
        border: 1px solid rgba(148, 163, 184, 0.14);
        border-radius: 10px;
        padding: 9px 16px; margin: 12px 0;
        font-family: 'JetBrains Mono', monospace;
        font-size: 11px; color: #64748b;
        letter-spacing: 0.3px;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
    }
    .hud-banner .status-val { color: #38bdf8; font-weight: 600; }

    /* ══════════════════════════════════════════════
       STATUS BADGES — Soft Classy Tones
    ══════════════════════════════════════════════ */
    .badge {
        display: inline-flex; align-items: center; gap: 4px;
        padding: 3px 9px; border-radius: 6px;
        font-family: 'JetBrains Mono', monospace;
        font-size: 10px; font-weight: 600;
        letter-spacing: 0.5px; text-transform: uppercase;
        border: 1px solid transparent;
    }
    .badge-DEFECT  { background: rgba(244, 63, 94, 0.14);  color: #fb7185; border-color: rgba(244, 63, 94, 0.3); }
    .badge-PASS    { background: rgba(16, 185, 129, 0.14); color: #34d399; border-color: rgba(16, 185, 129, 0.3); }
    .badge-UNCERTAIN{background: rgba(245, 158, 11, 0.14); color: #fbbf24; border-color: rgba(245, 158, 11, 0.3); }
    .badge-NOVEL   { background: rgba(168, 85, 247, 0.14); color: #c084fc; border-color: rgba(168, 85, 247, 0.3); }
    .badge-CRITICAL{ background: rgba(244, 63, 94, 0.14);  color: #fb7185; border-color: rgba(244, 63, 94, 0.35); }
    .badge-WARNING { background: rgba(245, 158, 11, 0.14); color: #fbbf24; border-color: rgba(245, 158, 11, 0.35); }
    .badge-OPTIMAL { background: rgba(16, 185, 129, 0.14); color: #34d399; border-color: rgba(16, 185, 129, 0.35); }
    .badge-HIGH    { background: rgba(244, 63, 94, 0.14);  color: #fb7185; border-color: rgba(244, 63, 94, 0.3); }
    .badge-MEDIUM  { background: rgba(245, 158, 11, 0.14); color: #fbbf24; border-color: rgba(245, 158, 11, 0.3); }
    .badge-LOW     { background: rgba(100, 116, 139, 0.14);color: #94a3b8; border-color: rgba(100, 116, 139, 0.3); }

    /* ══════════════════════════════════════════════
       EVIDENCE & ALERT CARDS
    ══════════════════════════════════════════════ */
    .evidence-box {
        background: linear-gradient(145deg, rgba(18, 27, 46, 0.8) 0%, rgba(10, 16, 30, 0.85) 100%);
        border: 1px solid rgba(148, 163, 184, 0.14);
        border-left: 3.5px solid #38bdf8;
        border-radius: 0 10px 10px 0;
        padding: 14px 18px; margin-bottom: 12px;
        box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
        transition: all 0.2s ease;
    }
    .evidence-box:hover { transform: translateX(3px); }
    .evidence-box.HIGH     { border-left-color: #f43f5e; }
    .evidence-box.CRITICAL { border-left-color: #f43f5e; }
    .evidence-box.MEDIUM   { border-left-color: #f59e0b; }
    .evidence-box.WARNING  { border-left-color: #f59e0b; }
    .evidence-box.LOW      { border-left-color: #475569; }
    .evidence-box.OPTIMAL  { border-left-color: #10b981; }

    /* ══════════════════════════════════════════════
       EXECUTIVE STAT CARDS
    ══════════════════════════════════════════════ */
    .stat-card {
        background: linear-gradient(180deg, rgba(22, 33, 54, 0.65) 0%, rgba(10, 15, 28, 0.85) 100%);
        border: 1px solid rgba(148, 163, 184, 0.14);
        border-top: 3px solid #38bdf8;
        border-radius: 12px;
        padding: 15px 16px;
        text-align: center;
        transition: all 0.22s ease;
        box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.05);
