    .stat-card.green  { border-top-color: #10b981; }
    .stat-card.red    { border-top-color: #f43f5e; }
    .stat-card.orange { border-top-color: #f59e0b; }
    .stat-card.purple { border-top-color: #a855f7; }
    .stat-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
    }
    .stat-card .val {
        font-family: 'JetBrains Mono', monospace;
        font-size: 1.6rem; font-weight: 700;
        color: #f8fafc; line-height: 1.15;
    }
    .stat-card .lbl {
        font-family: 'Plus Jakarta Sans', sans-serif;
        font-size: 11px; font-weight: 600;
        letter-spacing: 0.9px; text-transform: uppercase;
        color: #64748b; margin-top: 5px;
    }
    .stat-card .sub {
        font-family: 'JetBrains Mono', monospace;
        font-size: 10px; color: #475569; margin-top: 3px;
    }

    /* ══════════════════════════════════════════════
       SECTION DIVIDER
    ══════════════════════════════════════════════ */
    .section-divider {
        height: 1px;
        background: linear-gradient(90deg,
            transparent 0%,
            rgba(148, 163, 184, 0.15) 30%,
            rgba(56, 189, 248, 0.3) 50%,
            rgba(148, 163, 184, 0.15) 70%,
            transparent 100%);
        margin: 18px 0;
    }

    /* ══════════════════════════════════════════════
       PROGRESS BAR
    ══════════════════════════════════════════════ */
    .util-bar-wrap {
        background: rgba(148, 163, 184, 0.1);
        border-radius: 6px; height: 6px;
        overflow: hidden; margin: 6px 0;
    }
    .util-bar-fill {
        height: 100%; border-radius: 6px;
        background: linear-gradient(90deg, #38bdf8, #0284c7);
        transition: width 0.5s ease;
    }
    .util-bar-fill.danger { background: linear-gradient(90deg, #f43f5e, #e11d48); }
    .util-bar-fill.warn   { background: linear-gradient(90deg, #f59e0b, #d97706); }
    .util-bar-fill.safe   { background: linear-gradient(90deg, #10b981, #059669); }

    /* ══════════════════════════════════════════════
       ALERTS & TOASTS
    ══════════════════════════════════════════════ */
    [data-testid="stSpinner"] { color: #38bdf8 !important; }
    [data-testid="stAlert"] {
        border-radius: 10px !important;
        border: 1px solid rgba(148, 163, 184, 0.15) !important;
        background: rgba(13, 19, 33, 0.8) !important;
    }
    [data-testid="stInfo"] {
        border-left: 3px solid #38bdf8 !important;
        background: rgba(56, 189, 248, 0.05) !important;
    }
    [data-testid="stSuccess"] {
        border-left: 3px solid #10b981 !important;
        background: rgba(16, 185, 129, 0.05) !important;
    }
    [data-testid="stError"] {
        border-left: 3px solid #f43f5e !important;
        background: rgba(244, 63, 94, 0.05) !important;
    }
</style>
""", unsafe_allow_html=True)

